R=results/2026-10-07_2246_mcp-guided_opus-5.5-high; node -e "
const lines=require('fs').readFileSync('$R/transcript.jsonl','utf8').split('\n').filter(Boolean);
const uses=[];const res={};
for(const l of lines){let j;try{j=JSON.parse(l)}catch{continue}
 const c=j.message&&j.message.content; if(!Array.isArray(c))continue;
 for(const b of c){ if(b.type=='tool_use')uses.push(b); if(b.type=='tool_result')res[b.tool_use_id]=b;}}
const pick=[0,1,2].concat(uses.map((u,i)=>i).filter(i=>i>=uses.length-12));
for(const i of [...new Set(pick)]){const u=uses[i]; const r=res[u.id]; let out=r?(typeof r.content=='string'?r.content:JSON.stringify(r.content)):''; console.log('###',u.name,JSON.stringify(u.input).slice(0,600)); console.log('-->',out.slice(0,500));}
"

